public class StringUtils_indexOfAny_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;















    @Test
    public void testIndexOfAny_MultipleMatchesReturnsFirstOccurrenceInCS() {
        // 'b' is at index 1, 'a' is at index 0. 
        // The loop iterates through cs, so it should find 'a' first.
        assertEquals(0, StringUtils.indexOfAny("abc", new char[]{'b', 'a'}));
    }






}

